        "to_period": {
          "label": "FY2025",
          "start": "2025-01-01",
          "end": "2025-12-31"
        },
        "value": "3.09",
        "unit": "percent"
      }
    },
    {
      "claim_id": "C3",
      "text": "Noninterest revenue increased by 2.39% from $84,973 million in 2024 to $87,004 million in 2025, despite Other income decreasing from $12,462 million to $6,174 million, driven by the absence of the $7.9 billion ENTITY_04 gain recorded in 2024, partially offset by a $588 million ENTITY_05-related gain in 2025 and lower losses on certain equity investments.",
      "evidence_ids": ["EP_0005_E01", "EP_0005_E02"],
      "check_spec": {
        "kind": "percentage_change",
        "from_fact_id": "EP_0005_F06",
        "to_fact_id": "EP_0005_F05",
        "metric": "noninterest_revenue",
        "from_period": {
          "label": "FY2024",
          "start": "2024-01-01",
          "end": "2024-12-31"
        },
        "to_period": {
          "label": "FY2025",
          "start": "2025-01-01",
          "end": "2025-12-31"
        },
        "value": "2.39",
        "unit": "percent"
      }
    },
    {
      "claim_id": "C4",
      "text": "Provision for credit losses increased by 33.10% from $10,678 million in 2024 to $14,212 million in 2025, driven by a $1.6 billion increase in consumer provisions (primarily PRODUCT_26 loan growth and a $2.2 billion PRODUCT_27 transaction impact) and a $1.987 billion increase in wholesale provisions (portfolio growth, credit quality changes, and leveraged loan loss assumption updates).",
      "evidence_ids": ["EP_0005_E04"],
      "check_spec": {
        "kind": "percentage_change",
        "from_fact_id": "EP_0005_F08",
        "to_fact_id": "EP_0005_F07",
        "metric": "provision_for_credit_losses",
